// Entry point: global styles, database, offline support and a tiny router.
import './style.css';
import { db } from './db.js';
import { registerSW } from 'virtual:pwa-register';
import { renderProfile } from './pages/profile.js';
import { renderTimer, stopRun } from './pages/timer.js';
import { renderDashboard } from './pages/dashboard.js';
import { renderWorkouts } from './pages/workouts.js';
import { renderDiet } from './pages/diet.js';

// Register the service worker (generated by vite-plugin-pwa at build time).
// It caches the app so it keeps working offline.
registerSW({ immediate: true });

// --- Pages -------------------------------------------------------------
// Each feature lives in its own module under src/pages/ and exports a
// render(container) function. Unfinished ones show a placeholder.
const routes = {
  '/':         { title: 'Home',        render: renderDashboard },
  '/timer':    { title: 'Timer round', render: renderTimer },
  '/workouts': { title: 'Allenamenti', render: renderWorkouts },
  '/diet':     { title: 'Dieta',       render: renderDiet },
  '/weight':   { title: 'Peso',        render: placeholder('Peso reale vs peso stimato dal bilancio.') },
  '/profile':  { title: 'Profilo',     render: renderProfile },
};

function placeholder(text) {
  return (container) => {
    container.innerHTML = `
      <section class="card">
        <p>${text}</p>
        <p class="muted">In costruzione.</p>
      </section>`;
  };
}

const app = document.getElementById('app');
const title = document.getElementById('page-title');

// --- Router ------------------------------------------------------------
// The part after '#' in the URL decides which page to show.
// Hash routing needs no server configuration, so it works on GitHub Pages
// and offline.
async function router() {
  stopRun(); // leaving the timer page stops a running timer

  // First launch: no profile yet -> welcome screen instead of the app
  const profile = await db.profile.get('me');
  if (!profile) {
    document.body.classList.add('onboarding'); // hides the tab bar (see CSS)
    title.textContent = 'FightFit';
    await renderProfile(app, {
      onboarding: true,
      onSaved: () => {
        document.body.classList.remove('onboarding');
        location.hash = '#/';
        router(); // hash may already be '#/', so call it explicitly
      },
    });
    return;
  }

  const path = location.hash.slice(1) || '/';
  const route = routes[path] ?? routes['/'];

  title.textContent = route.title;
  await route.render(app);

  // Highlight the active tab
  document.querySelectorAll('.tabbar a').forEach((a) => {
    a.classList.toggle('active', a.dataset.route === path);
  });
}

window.addEventListener('hashchange', router);
router();
